const model=id=>data.models.find(m=>m.id===id);
const categoryOf=m=>m.category||(/กางเกงใน/.test(m.name)?'กางเกงใน':'เสื้อใน');
const subcategoryOf=m=>m.subcategory||'ไม่ระบุหมวดย่อย';
const categories=()=>[...new Set(data.models.map(categoryOf))];
const subcategories=category=>[...new Set(data.models.filter(m=>category==='ทั้งหมด'||categoryOf(m)===category).map(subcategoryOf))];
const numericSizes=['28','30','32','34','36','38','40','42','44','46','48'];
const alphaSizes=['XS','S','M','L','XL','2XL','3XL','4XL'];
function validSize(value,system){if(!value||value.length>24||value.includes(':')||value.includes('·'))return false;if(system==='numeric')return /^\d{1,3}$/.test(value)&&Number(value)>0;if(system==='alpha')return /^\d*[A-Z]{1,5}$/.test(value);return true}
// One stock count belongs to one sellable pack variant, never to the model total.
// A mixed-color pack has one variant per size; a single-color pack has size × color variants.
const newVariantKeys=n=>n.sizes.flatMap(size=>(n.mixed?['คละสี']:(n.colors[size]||[])).map(color=>({size,color,key:size+':'+color})));
const validPackCount=n=>n!==''&&Number.isInteger(Number(n))&&Number(n)>=1&&Number(n)<=99;
const validAlertThreshold=n=>n!==''&&Number.isInteger(Number(n))&&Number(n)>=0&&Number(n)<=999;
const validStockCount=n=>typeof n==='number'&&Number.isInteger(n)&&n>=0&&n<=999;
const stockSummary=n=>{const keys=newVariantKeys(n),values=keys.map(x=>n.stocks[x.key]),filled=values.filter(validStockCount).length,invalid=values.some(x=>x!==undefined&&!validStockCount(x)),packs=values.filter(validStockCount).reduce((sum,x)=>sum+x,0);return {keys,filled,invalid,packs,pieces:packs*n.pack,complete:filled===keys.length&&!invalid}};
const variant=(m,v)=>model(m)?.variants.find(x=>x.id===v);
