const field=(label,key,value,helper='',type='text')=>`<label class="field"><span class="label">${label}</span><input class="input" type="${type}" data-field="${key}" value="${esc(value)}">${helper?`<div class="helper">${helper}</div>`:''}</label>`;
const note=(text,kind='')=>`<div class="notice ${kind}">${text}</div>`;
