const nav=()=>`<nav class="nav" aria-label="เมนูหลัก">${[['home','home','หน้าแรก'],['models','stock','สต็อก'],['bills','bill','บิล'],['reservations','reservation','จอง']].map(([id,symbol,label])=>`<button type="button" class="${activeTab===id?'active':''}" data-action="switch-tab" data-to="${id}" aria-label="${label}${tabMemory[id]!==id?' กลับไปงานที่ค้างไว้':''}" ${activeTab===id?'aria-current="page"':''}>${icon(symbol)}<span class="nav-label">${label}</span>${tabMemory[id]!==id&&activeTab!==id?'<span class="nav-resume" aria-hidden="true"></span>':''}</button>`).join('')}</nav>`;
