function tabForPage(to){if(['models','stock','model-price','initialize','adjust','history','low-stock','model-new'].includes(to))return 'models';if(to==='bill-preview')return previewReservationId?'reservations':'bills';if(['bills','bill-new','bill-done'].includes(to))return 'bills';if(to==='pick')return pickFor==='reservation'?'reservations':'bills';if(['reservations','reservation-new','reservation-detail'].includes(to))return 'reservations';return 'home'}
function saveTab(){tabMemory[activeTab]=page;if(activeTab==='bills'||activeTab==='reservations')draftContexts[activeTab]={draft,pickFor,pickQty,pickSearch,pickCategory,pickSubcategory,pickOpenModel,pickOpenSize,pickShowCart,expandedDraftIndex,editingBillId,editingReservationId}}
function restoreDraft(tab){const saved=draftContexts[tab];if(saved){({draft,pickFor,pickQty,pickSearch,pickCategory,pickSubcategory,pickOpenModel,pickOpenSize,pickShowCart,expandedDraftIndex,editingBillId,editingReservationId}=saved)}}
function switchTab(tab){if(!tabs.includes(tab))return;editingLinePriceIndex=null;if(tab===activeTab){page=tab==='bills'&&role==='owner'?'bill-new':tab;tabMemory[tab]=page;tabStacks[tab]=[];if(tab==='reservations')reservationFilter=null}else{saveTab();activeTab=tab;restoreDraft(tab);page=tab==='bills'&&role!=='owner'?'bills':tabMemory[tab]}modal=null;toast='';render()}
function go(to){const target=tabForPage(to);if(target!==activeTab){saveTab();activeTab=target;restoreDraft(target);tabStacks[target]=to===target?[]:[target]}else if(page!==to){tabStacks[target].push(page)}if(to==='reservations')reservationFilter=null;if(to==='pick')pickShowCart=false;page=to;modal=null;toast='';render()}
function back(){if(page==='model-new'&&newModel.step>1){newModel.step=newModel.step===4&&newModel.mixed?2:newModel.step-1;return render()}const afterSave={'receipt-detail':'home','bill-done':'bill-new','reservation-detail':'reservations',history:'stock'};if(afterSave[page]){page=afterSave[page];tabStacks[activeTab]=[];modal=null;return render()}page=tabStacks[activeTab].pop()||activeTab;modal=null;render()}
function noticeToast(t){toast=t;render()}
function lineAmount(l){return l.qty*l.price}
function draftTotal(){return draft.lines.reduce((n,l)=>n+lineAmount(l),0)}
function lineLabel(l){const m=model(l.m);return `${m.name} · ${variant(l.m,l.v)?.label||l.v}`}
function changeStock(m,v,delta,reason){const x=variant(m,v);x.onHand+=delta;data.history.unshift({m,v,delta,reason,when:new Date().toLocaleString('th-TH')})}
function newDraft(forWhat){if(role!=='owner')return;pickFor=forWhat;previewReservationId=null;go(forWhat==='bill'?'bill-new':'reservation-new');pickFor=forWhat;draft={customer:'',lines:[]};expandedDraftIndex=null;editingLinePriceIndex=null;pickQty={};pickSearch='';pickCategory='ทั้งหมด';pickSubcategory='ทั้งหมด';pickOpenModel=null;pickOpenSize=null;pickShowCart=false;if(forWhat==='bill')editingBillId=null;else editingReservationId=null;render()}
function draftLine(m,v){return draft.lines.find(l=>l.m===m&&l.v===v)}
function editableAvailable(l){const ownBill=editingBillId?data.bills.find(b=>b.id===editingBillId)?.lines.find(z=>z.m===l.m&&z.v===l.v)?.qty||0:0;const ownReservation=editingReservationId?data.reservations.find(r=>r.id===editingReservationId)?.lines.find(z=>z.m===l.m&&z.v===l.v)?.qty||0:0;return available(variant(l.m,l.v))+ownBill+ownReservation}
function draftPriceEditor(l,i){const open=role==='owner'&&editingLinePriceIndex===i,canSave=validPrice(linePriceDraft);return `<div class="row draft-price"><span>${money(l.price)} / แพ็ก</span><strong>${money(lineAmount(l))}</strong></div>${role==='owner'?`<button class="line-price-trigger" data-action="edit-price" data-index="${i}">${icon('tag')}<span>ราคาเฉพาะ${page==='reservation-new'?'การจอง':'บิล'}นี้</span></button>`:''}${open?`<div class="inline-price-editor"><label class="field"><span class="label">ราคาใหม่ / แพ็ก (บาท)</span><input class="input" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" data-field="line-price" value="${esc(linePriceDraft)}" aria-describedby="line-price-hint line-price-error" aria-invalid="${!!linePriceError}"></label><p id="line-price-hint" class="helper">แก้เฉพาะรายการนี้ ราคาประจำรุ่นยังเท่าเดิม</p><p id="line-price-error" class="field-error" role="alert">${esc(linePriceError)}</p><div class="grid2">${btn('บันทึกราคา','save-line-price','full',`data-index="${i}" ${canSave?'':'disabled'}`)}${btn('ยกเลิก','cancel-line-price','secondary full')}</div></div>`:''}`}
function draftCard(l,i){const m=model(l.m),v=variant(l.m,l.v),canDozen=12%m.pack===0,max=editableAvailable(l),dozenPacks=12/m.pack,displayQty=l.unit==='dozen'?l.qty/dozenPacks:l.qty;
  return card(`<div class="row start"><div class="stack"><strong>${esc(m.name)}</strong><span class="muted small">ไซซ์ ${esc(v.label)} · ขายได้ ${available(v)} แพ็ก</span></div><button class="remove-model" data-action="remove-line" data-index="${i}" aria-label="ลบรายการ">×</button></div>${canDozen?`<div class="draft-unit">${selection([['pack','แพ็ก'],['dozen','โหล']],l.unit,'line-unit').replaceAll('data-action="line-unit"',`data-action="line-unit" data-index="${i}"`)}${l.unit==='dozen'?`<span class="muted small">1 โหล = ${dozenPacks} แพ็ก</span>`:''}</div>`:''}<div class="draft-quantity">${stepper('line:'+i,displayQty,1,999)}<span class="muted small">${l.unit==='dozen'?'โหล':'แพ็ก'}</span></div>${draftPriceEditor(l,i)}${l.qty>max?note(`สต็อกไม่พอ เหลือขายได้ ${max} แพ็ก`,'error'):''}`,'draft-line')
}
function draftCards(){if(draft.lines.length<=5)return draft.lines.map(draftCard).join('');return `<h2 class="section-title">${page==='reservation-new'?'รายการที่จอง':'รายการในบิล'} <span class="muted small">${draft.lines.length} รายการ · แตะเพื่อแก้ไข</span></h2><div class="card compact-lines">${draft.lines.map((l,i)=>i===expandedDraftIndex?`<div class="expanded-line">${draftCard(l,i)}${btn('ย่อรายการ','collapse-draft-line','secondary full')}</div>`:`<button class="compact-line" data-action="expand-draft-line" data-index="${i}"><span class="stack"><strong>${esc(model(l.m).name)}</strong><span class="muted small">${esc(variant(l.m,l.v).label)} · ${l.qty} แพ็ก</span></span><strong>${money(lineAmount(l))}</strong></button>`).join('')}</div>`}
function renderHome(){
  const low=data.models.flatMap(m=>m.variants.filter(v=>available(v)<=m.min).map(v=>[m,v]));
  const sellable=data.models.reduce((sum,m)=>sum+m.variants.reduce((n,v)=>n+available(v),0),0);
  const pending=data.reservations.filter(r=>r.status==='active');
  const reserved=pending.length;
  const shortcuts=[['models','stock','ดูสต็อก'],['new-bill','bill','ออกบิล'],['new-reservation','reservation','จอง'],['new-receipt','truck','รับของเข้า']];
  return shell(data.shop,'ยินดีต้อนรับ · ข้อมูลตัวอย่าง',`${toast?note(toast,'good'):''}
    ${card(`<div class="home-wordmark" role="img" aria-label="khonnai"></div><h2>งานของร้านวันนี้</h2><p class="muted">มี ${sellable} แพ็กขายได้ · ${reserved} รายการจอง · ${low.length} ตัวเลือกใกล้หมด</p>${btn('ดูสต็อกทั้งหมด','go','full','data-to="models"')}`,'home-hero')}
    <h2 class="section-title">ทางลัด</h2>
    <div class="home-shortcuts">${shortcuts.map(([action,symbol,label])=>`<button class="shortcut" data-action="${action==='models'?'go':action}" ${action==='models'?'data-to="models"':''} ${role==='assistant'&&['new-bill','new-reservation'].includes(action)?'disabled':''}><span class="shortcut-icon">${icon(symbol)}</span><strong>${label}</strong></button>`).join('')}</div>
    <button class="card tapcard share-shortcut" data-action="go" data-to="share"><span class="shortcut-icon">${icon('stock')}</span><span class="stack"><strong>แชร์แคตตาล็อก</strong><span class="muted small">ส่งลิงก์ให้ลูกค้าประจำในกลุ่ม LINE</span></span><span class="chevron" aria-hidden="true">›</span></button>
    ${pending.length?card(`<strong>การจองที่รอปิดบิล</strong>${pending.slice(-2).reverse().map(r=>`<button class="listrow" data-action="open-reservation" data-id="${r.id}"><span>${esc(r.customer)}<br><span class="muted small">${r.lines.reduce((n,l)=>n+l.qty,0)} แพ็ก · ${r.id}</span></span><span class="right">${money(r.total)} ›</span></button>`).join('')}`):''}
    <details class="test-tools"><summary>เครื่องมือสำหรับทดสอบ</summary><div class="screen-note">${btn(role==='owner'?'สลับเป็นผู้ช่วยร้าน':'สลับเป็นเจ้าของร้าน','switch-role','ghost full')}${btn('รีเซ็ตข้อมูลทดสอบ','reset','ghost full')}</div></details>`, '',true,false)
}
function renderModels(){const active=data.models.filter(m=>!m.hidden).length,hidden=data.models.length-active;return shell('รุ่นทั้งหมด',`${data.models.length} รุ่น`,`${field('ค้นหารุ่น','model-search',search.model||'','ชื่อ รุ่น รหัส หรือหมวดย่อย')}<div class="chiprow stock-filters">${selection([['active',`กำลังขาย (${active})`],['hidden',`เลิกขาย (${hidden})`]],stockFilter,'stock-filter')}</div><div class="chiprow category-filters">${selection([['ทั้งหมด','ทั้งหมด'],...categories().map(x=>[x,x])],stockCategory,'stock-category')}</div><div class="chiprow subcategory-filters">${selection([['ทั้งหมด','ทุกหมวดย่อย'],...subcategories(stockCategory).map(x=>[x,x])],stockSubcategory,'stock-subcategory')}</div><div id="model-results">${modelResults()}</div>`,role==='owner'?btn('+ เพิ่มรุ่น','new-model','full'):'',false,false)}
const search={model:''};
function modelCard(m){const sellable=m.variants.reduce((n,v)=>n+available(v),0);return `<button class="card tapcard model-card" data-action="open-stock" data-model="${m.id}"><div class="row">${productThumb(m)}<div class="stack" style="flex:1"><span class="product-eyebrow">${esc(m.id)} · ${esc(subcategoryOf(m))}</span><strong>${esc(m.name)}</strong><span class="muted small">${m.pack} ตัว/แพ็ก · ${sellable?`ขายได้ ${sellable} แพ็ก`:'ของหมด'}</span><span class="model-price">${money(m.price)} / แพ็ก</span></div><span class="chevron" aria-hidden="true">›</span></div></button>`}
function modelPriceCard(m){return `<section class="card current-price"><span class="muted small">ราคาขายปัจจุบัน</span><div class="row"><strong>${money(m.price)} <small>/ แพ็ก</small></strong>${role==='owner'?`<button class="price-change" data-action="open-model-price">${icon('tag')}<span>แก้ราคา</span></button>`:''}</div><p class="muted small">ราคาใหม่นำไปใช้กับบิลและการจองที่เริ่มใหม่ · สต็อกไม่เปลี่ยน</p></section>`}
function modelResults(){const q=search.model.trim().toLowerCase(),filtered=data.models.filter(m=>m.hidden===(stockFilter==='hidden')&&(stockCategory==='ทั้งหมด'||categoryOf(m)===stockCategory)&&(stockSubcategory==='ทั้งหมด'||subcategoryOf(m)===stockSubcategory)&&(!q||(m.name+m.id+categoryOf(m)+subcategoryOf(m)).toLowerCase().includes(q)));return categories().map(category=>{const rows=filtered.filter(m=>categoryOf(m)===category);return rows.length?`<section class="model-group"><h2 class="section-title">${esc(category)} <span class="muted small">${rows.length} รุ่น</span></h2>${[...new Set(rows.map(subcategoryOf))].map(sub=>`<div class="model-subgroup"><h3>${esc(sub)}</h3>${rows.filter(m=>subcategoryOf(m)===sub).map(modelCard).join('')}</div>`).join('')}</section>`:''}).join('')||note(stockFilter==='hidden'?'ยังไม่มีรุ่นที่เลิกขาย':'ไม่พบรุ่นที่ค้นหา')}
function renderStock(){const m=model(selectedModel),on=m.variants.reduce((n,v)=>n+v.onHand,0),res=m.variants.reduce((n,v)=>n+v.reserved,0);return shell(m.name,`${esc(categoryOf(m))} / ${esc(subcategoryOf(m))} · ${m.pack} ตัว/แพ็ก`,`${toast?note(esc(toast),toast.includes('ไม่ได้')?'error':'good'):''}${role==='assistant'?note('คุณเข้าใช้ในฐานะผู้ช่วยร้าน ดูสต็อกได้ แต่ปรับยอดไม่ได้'):''}${m.hidden?note('เลิกขายแล้ว · ไม่แสดงในหน้าขายและแคตตาล็อก แต่บิลและประวัติยังอยู่','warn'):''}${!m.initialized?note('ยังไม่ได้กรอกสต็อกตั้งต้น รุ่นนี้ยังไม่แสดงในแคตตาล็อก','warn'):''}${modelPriceCard(m)}<div class="grid3 stock-summary">${[['ในร้าน',on],['จองไว้',res],['ขายได้',on-res]].map(([lab,n])=>`<div class="stat"><span>${lab}</span><strong>${n}</strong><em>แพ็ก</em></div>`).join('')}</div><p class="muted small">ขายได้ = ของในร้าน − ของที่ลูกค้าจองไว้</p>${photoEditor(m,'model-photo',role==='owner')}<div class="card stock-table"><div class="stock-row stock-head"><span>ไซซ์ · สี</span><span>ในร้าน</span><span>จอง</span><span>ขายได้</span><span></span></div>${m.variants.map(v=>`<button class="stock-row stock-item" data-action="open-adjust" data-model="${m.id}" data-variant="${v.id}"><span class="stack"><strong>${esc(v.label)}</strong>${status(m,v)!=='มีของ'?badge(status(m,v)):''}</span><span>${v.onHand}</span><span>${v.reserved}</span><strong class="${available(v)===0?'out-of-stock':''}">${available(v)}</strong><span class="chevron" aria-hidden="true">›</span></button>`).join('')}</div>${role==='owner'?`<div class="lifecycle-action">${btn(m.hidden?'นำรุ่นนี้กลับมาขาย':'เลิกขายรุ่นนี้',m.hidden?'restore-model':'ask-hide-model','ghost full')}</div>`:''}`,role==='owner'?`<div class="grid2 stock-actions">${m.initialized?btn('ปรับยอด','open-adjust','secondary full',`data-model="${m.id}" data-variant="${m.variants[0].id}"`):btn('กรอกสต็อกตั้งต้น','go','full','data-to="initialize"')}${btn('ประวัติ','go','secondary full','data-to="history"')}</div>`:btn('ประวัติ','go','secondary full','data-to="history"'),false)}
function renderModelPrice(){const m=model(selectedModel),valid=validPrice(modelPriceDraft),next=Number(modelPriceDraft),changed=valid&&next!==m.price,difference=valid?next-m.price:0;return shell('แก้ราคาขาย',m.name,`
  <section class="card price-context"><span class="muted small">ราคาปัจจุบัน</span><strong>${money(m.price)} / แพ็ก</strong><p class="muted small">สต็อกและจำนวนตัวต่อแพ็กจะไม่เปลี่ยน</p></section>
  <label class="field"><span class="label">ราคาขายใหม่ / แพ็ก (บาท)</span><input class="input" type="number" inputmode="decimal" min="0.01" max="1000000" step="0.01" data-field="model-price" value="${esc(modelPriceDraft)}" aria-describedby="model-price-hint model-price-error" aria-invalid="${!!modelPriceError}"></label>
  <p id="model-price-hint" class="helper">กรอกราคามากกว่า 0 บาท ทศนิยมได้ไม่เกิน 2 ตำแหน่ง</p>
  <p id="model-price-error" class="field-error" role="alert">${esc(modelPriceError)}</p>
  <div class="card price-preview"><div class="row"><span>ก่อนแก้</span><strong>${money(m.price)}</strong></div><div class="row"><span>ราคาใหม่</span><strong data-new-price>${valid?money(next):'—'}</strong></div><div class="row"><span>ส่วนต่าง</span><strong data-price-difference>${valid?`${difference>0?'+':difference<0?'-':''}${money(Math.abs(difference))}`:'—'}</strong></div></div>
  ${note('ราคาใหม่จะใช้กับบิลและการจองที่เริ่มหลังบันทึก บิลที่ออกแล้ว การจองเดิม และร่างที่กำลังทำจะคงราคาที่บันทึกไว้','warn')}
  ${(m.priceHistory||[]).length?`<section class="card price-history"><strong>ประวัติการเปลี่ยนราคา</strong>${m.priceHistory.slice(-3).reverse().map(h=>`<div class="row"><span>${money(h.from)} → ${money(h.to)}</span><span class="muted small">${esc(h.when)}</span></div>`).join('')}</section>`:''}
`,`${btn('บันทึกราคาใหม่','save-model-price','full',changed?'':'disabled')}${btn('ยกเลิก','back','secondary full')}`)}
function renderInitialize(){const m=model(selectedModel);return shell('สต็อกตั้งต้น',m.name,`${note('กรอกจำนวนในร้านที่นับได้จริงเป็นแพ็ก')}${m.variants.map(v=>card(`<strong>${esc(v.label)}</strong>${stepper('init:'+v.id,initialStocks[v.id]||0)}`)).join('')}`,btn('บันทึกสต็อกตั้งต้น','save-initialize','full'))}
let initialStocks={};
function renderAdjust(){const m=model(selectedModel),v=variant(selectedModel,selectedVariant),bad=adjustment.count<v.reserved,diff=adjustment.count-v.onHand;return shell('ปรับยอด',`${m.id} · ${v.label}`,`${card(`<div class="row"><span>ในร้านตามระบบ</span><strong>${v.onHand} แพ็ก</strong></div><div class="row"><span>ลูกค้าจองไว้</span><strong>${v.reserved} แพ็ก</strong></div><div class="row"><span>ขายได้</span><strong>${available(v)} แพ็ก</strong></div>`)}${card(`<strong>นับได้จริงกี่แพ็ก?</strong><p class="muted small">นับของบนชั้นทั้งหมด รวมของที่ลูกค้าจองไว้ด้วย</p>${stepper('adjust-count',adjustment.count)}${bad?note(`ตั้งต่ำกว่าจำนวนที่จองไม่ได้ มีลูกค้าจองไว้ ${v.reserved} แพ็ก`,'error'):note(`ในร้านจะ${diff<0?'ลด':'เพิ่ม'} ${Math.abs(diff)} แพ็ก · ขายได้จะเหลือ ${adjustment.count-v.reserved} แพ็ก`)}`)}${card(`<strong>เหตุผล (ต้องเลือก)</strong>${selection(['นับผิด','ของเสีย','ของหาย','สต็อกตั้งต้น'].map(x=>[x,x]),adjustment.reason,'adjust-reason')}`)}`,`${btn('บันทึกการปรับยอด','save-adjust','full',bad||!adjustment.reason?'disabled':'')}${v.reserved?btn('ดูการจองของไซซ์นี้','reservations-for-variant','secondary full'):''}`)}
function renderHistory(){return shell('ประวัติสต็อก',`${selectedModel} · ${selectedVariant}`,data.history.filter(h=>h.m===selectedModel&&h.v===selectedVariant).map(h=>card(`<div class="row"><strong>${esc(h.reason)}</strong><strong>${h.delta>0?'+':''}${h.delta} แพ็ก</strong></div><p class="muted small">${h.when} · ${role==='owner'?'เจ๊หน่อย':'มิ้น'}</p>`)).join('')||note('ยังไม่มีประวัติสำหรับตัวเลือกสินค้านี้'))}
function renderLow(){const rows=data.models.flatMap(m=>m.variants.filter(v=>available(v)<=m.min).map(v=>({m,v}))).sort((a,b)=>available(a.v)-available(b.v));return shell('ใกล้หมด',`${rows.length} รายการ · ใช้ตอนสั่งของจากยี่ปั๊ว`,rows.map(({m,v})=>`<button class="card tapcard" data-action="open-stock" data-model="${m.id}"><strong>${esc(m.name)}</strong><div class="row"><span>${esc(v.label)} · ขายได้ ${available(v)} / ขั้นต่ำ ${m.min}</span>${badge(status(m,v))}</div></button>`).join(''))}
function receiptGrid(m){
  const rows=[...new Set(m.variants.map(v=>v.label.split(' · ')[0]))];
  const colors=[...new Set(m.variants.map(v=>v.label.split(' · ')[1]))];
  const cells=(size,color)=>m.variants.find(v=>v.label===`${size} · ${color}`);
  const lines=receiptLines.filter(l=>l.m===m.id),sum=lines.reduce((n,l)=>n+l.qty,0),open=receiptOpenModel===m.id;
  return card(`<div class="row start"><button class="model-toggle" data-action="toggle-receipt-model" data-model="${m.id}" aria-expanded="${open}"><span class="stack"><strong>${esc(m.name)}</strong><span class="muted small">${lines.length} ตัวเลือก · ${sum} แพ็ก${open?' · กรอกจำนวนด้านล่าง':''}</span></span><span class="chevron" aria-hidden="true">${open?'⌃':'›'}</span></button><button class="remove-model" data-action="remove-receipt-model" data-model="${m.id}" aria-label="นำรุ่น ${esc(m.name)} ออกจากรอบรับของ">×</button></div>${open?`<div class="receipt-grid" style="--receipt-columns:${colors.length}"><div class="receipt-grid-head"><span>ไซซ์</span>${colors.map(color=>`<span>${color}</span>`).join('')}</div>${rows.map(size=>`<div class="receipt-grid-row"><strong>${esc(size)}</strong>${colors.map(color=>{const v=cells(size,color);if(!v)return '<span class="receipt-grid-missing">—</span>';const value=receiptLines.find(l=>l.m===m.id&&l.v===v.id)?.qty||0;return `<input type="number" inputmode="numeric" min="0" max="999" data-field="receipt-grid:${m.id}:${v.id}" value="${value}" aria-label="${esc(m.name)} ${esc(v.label)} จำนวนแพ็ก">`}).join('')}</div>`).join('')}</div>`:''}`,'receipt-model-card')
}
function receiptSearchResults(){const q=receiptSearch.trim().toLowerCase();if(!q)return '<p class="muted small">พิมพ์ชื่อ รหัส หรือหมวดย่อย เพื่อเพิ่มหลายรุ่นในรอบเดียว</p>';const matches=data.models.filter(m=>m.initialized&&!receiptModels.includes(m.id)&&(m.name+m.id+categoryOf(m)+subcategoryOf(m)).toLowerCase().includes(q)).slice(0,8);return matches.map(m=>`<button class="search-result" data-action="add-receipt-model" data-model="${m.id}"><span class="stack"><strong>${esc(m.name)}</strong><span class="muted small">${esc(categoryOf(m))} / ${esc(subcategoryOf(m))} · ${m.variants.length} ตัวเลือก</span></span><span class="chevron">+</span></button>`).join('')||note('ไม่พบรุ่นที่ค้นหา')}
function renderReceive(){
  const sum=receiptLines.reduce((n,l)=>n+l.qty,0);
  const visibleIds=[...new Set([...receiptModels,...receiptLines.map(l=>l.m)])].filter(id=>model(id));
  return shell(editingReceiptId?'แก้ไขการรับของเข้า':'รับของเข้า',editingReceiptId?`แก้รายการ ${editingReceiptId} แล้วบันทึกยอดใหม่`:'ค้นรุ่น แล้วกรอกจำนวนจากบิลยี่ปั๊ว',`${toast?note(toast,'error'):''}${field('ยี่ปั๊ว','supplier',receipt.supplier)}${field('วันที่รับของ','receipt-date',receipt.date,'','date')}${field('เพิ่มรุ่นในรอบนี้','receipt-search',receiptSearch,'พิมพ์ชื่อหรือรหัส เช่น A-215')}<div id="receipt-search-results">${receiptSearchResults()}</div>${visibleIds.length?`<h2 class="section-title">รุ่นที่รับเข้า <span class="muted small">${visibleIds.length} รุ่น</span></h2>${visibleIds.map(id=>receiptGrid(model(id))).join('')}`:note('ยังไม่มีรุ่นในรอบนี้ ค้นหาแล้วกดเพิ่มรุ่น')}`,`<div class="row"><span data-receipt-count>รวม ${receiptLines.length} รายการ</span><strong data-receipt-total>${sum} แพ็ก</strong></div>${btn(editingReceiptId?'บันทึกการแก้ไข':'บันทึกรับของเข้า','save-receipt','full',!receipt.supplier.trim()||!receiptLines.length?'disabled':'')}`)
}
function renderReceiptDetail(){const r=data.receipts.find(x=>x.id===receiptId);return shell(`รับของเข้า ${r.id}`,`${r.date} · ${r.supplier}`,`${toast?note(toast,toast.includes('ไม่ได้')?'error':'good'):''}${note(r.status==='active'?'บันทึกแล้ว · สต็อกเพิ่มขึ้น '+r.lines.reduce((n,l)=>n+l.qty,0)+' แพ็ก':'ยกเลิกแล้ว · ตัดยอดรับเข้านี้ออกจากสต็อก',r.status==='active'?'good':'warn')}${card(r.lines.map(l=>`<div class="row"><span>${esc(lineLabel(l))}</span><strong>${l.qty} แพ็ก</strong></div>`).join(''))}`,`${r.status==='active'?`${btn('แก้ไขรายการ','edit-receipt','secondary full')}${btn('ยกเลิกการรับของเข้า','ask-cancel-receipt','danger full')}`:''}${btn('รับของเข้าอีก','new-receipt','ghost full')}`)}
function renderBill(){const total=draftTotal(),error=draft.lines.some(l=>l.qty>(available(variant(l.m,l.v))+(editingBillId?data.bills.find(b=>b.id===editingBillId)?.lines.find(z=>z.m===l.m&&z.v===l.v)?.qty||0:0)));return shell(editingBillId?'แก้บิล':'ออกบิล',editingBillId?editingBillId:'เพิ่มสินค้า แล้วให้ลูกค้าตรวจยอด',`${error?note('สต็อกไม่พอ ลดจำนวนในรายการที่แจ้งแล้วลองอีกครั้ง','error'):''}${field('ลูกค้า','customer',draft.customer,'ใส่ชื่อเพื่อให้ลูกค้าตรวจว่าเป็นรายการของตน')}${draft.lines.length?draftCards():card('<strong>ยังไม่มีสินค้าในบิล</strong><p class="muted small">กดเพิ่มสินค้า เลือกรุ่น ไซซ์ และจำนวนแพ็กที่ลูกค้าซื้อ</p>','empty-hint')}${btn('+ เพิ่มสินค้า','go','secondary full','data-to="pick"')}${btn('ดูประวัติบิล','go','ghost full','data-to="bills"')}`,`<div class="row"><span>ยอดรวม</span><span class="total">${money(total)}</span></div>${btn('ดูสรุปยอดก่อนออกบิล','preview-bill','full',!draft.customer.trim()||!draft.lines.length||error?'disabled':'')}`)}
// The paper-like layout is shared by an estimate and the issued bill. An estimate
// never changes stock and is explicitly marked so it cannot be mistaken for a sale.
function billPaper(doc,final){return `<article class="cash-slip" aria-label="${final?'บิลเงินสด':'สรุปยอดเบื้องต้น'}"><div class="cash-slip-head"><strong>${esc(data.shop)}</strong><span>${final?'บิลเงินสด':'สรุปยอดเบื้องต้น'}</span><small>${final?esc(doc.id)+' · '+esc(doc.when):'ให้ลูกค้าตรวจยอดก่อนยืนยันขาย'}</small></div><div class="cash-slip-customer"><span>ลูกค้า</span><strong>${esc(doc.customer)}</strong></div><div class="cash-slip-columns" aria-hidden="true"><span>รายการสินค้า</span><span>จำนวน × ราคา</span><span>รวม</span></div>${doc.lines.map(l=>`<div class="cash-slip-line"><div><strong>${esc(model(l.m).name)}</strong><small>ไซซ์ / สี ${esc(variant(l.m,l.v).label)}</small></div><span>${l.qty} × ${money(l.price)}</span><strong>${money(lineAmount(l))}</strong></div>`).join('')}<div class="cash-slip-total"><span>ยอดรวมทั้งสิ้น</span><strong>${money(doc.total)}</strong></div><p class="cash-slip-note">${final?'เอกสารแสดงรายการขาย · ยังไม่ได้บันทึกสถานะการชำระเงิน':'ยังไม่ใช่บิลเงินสด · ยังไม่ตัดสต็อก'}</p></article>`}
function renderBillPreview(){const r=previewReservationId?data.reservations.find(x=>x.id===previewReservationId):null,doc=r||{customer:draft.customer,lines:draft.lines,total:draftTotal()};if(!doc)return renderBill();return shell('ตรวจยอดก่อนขาย',r?`จากการจอง ${esc(r.id)}`:'ให้ลูกค้าดูยอดก่อนออกบิล',`${r?note('ของยังจองไว้ ยอดนี้ยังไม่ตัดสต็อก','warn'):note('ให้ลูกค้าตรวจชื่อ รายการ จำนวน และยอดรวมก่อนยืนยัน','warn')}${billPaper(doc,false)}`,`<div class="row preview-total"><span>ยอดรวม</span><strong>${money(doc.total)}</strong></div>${btn(r?'ยืนยันขายจากการจอง':'ยืนยันออกบิล',r?'convert-reservation':'save-bill','full')}<div class="grid2 preview-secondary">${btn('แก้ไขรายการ','back','secondary full')}${btn('พิมพ์ / PDF','print','secondary full')}</div>`)}
function pickMetrics(){const chosen=Object.entries(pickQty).filter(([,qty])=>Number(qty)>0);return {lines:chosen.length,packs:chosen.reduce((n,[,qty])=>n+Number(qty),0),total:chosen.reduce((n,[key,qty])=>n+Number(qty)*model(key.split(':')[0]).price,0)}}
// Reveal one size's colors at a time. Quantities remain keyed by the full variant,
// so changing sizes never discards the other colors already chosen for this bill.
const pickSize=v=>v.label.split(' · ')[0];
const pickColor=v=>v.label.split(' · ').slice(1).join(' · ')||v.label;
const pickSizes=m=>[...new Set(m.variants.map(pickSize))];
const pickedInSize=(m,size)=>m.variants.filter(v=>pickSize(v)===size).reduce((sum,v)=>sum+Number(pickQty[m.id+':'+v.id]||0),0);
function defaultPickSize(m){const sizes=pickSizes(m),query=pickSearch.trim().toLowerCase();return sizes.find(s=>s.toLowerCase()===query)||sizes.find(s=>pickedInSize(m,s)>0)||sizes.find(s=>m.variants.some(v=>pickSize(v)===s&&available(v)>0))||sizes[0]||null}
function pickModelCard(m){
  const chosen=pickSizes(m).reduce((sum,size)=>sum+pickedInSize(m,size),0),open=pickOpenModel===m.id;
  const sizes=pickSizes(m),size=sizes.includes(pickOpenSize)?pickOpenSize:defaultPickSize(m);
  const colors=m.variants.filter(v=>pickSize(v)===size);
  return `<section class="pick-model card"><button class="model-toggle" data-action="toggle-pick-model" data-model="${esc(m.id)}" aria-expanded="${open}"><span class="stack"><strong>${esc(m.name)}</strong><span class="muted small">${esc(categoryOf(m))} / ${esc(subcategoryOf(m))} · ${money(m.price)} / แพ็ก</span></span><span class="pick-model-end"><span class="pick-model-count" data-pick-model-count="${esc(m.id)}">${chosen?chosen+' แพ็ก':''}</span><span class="chevron" aria-hidden="true">${open?'⌃':'›'}</span></span></button>${open?`<div class="pick-variants"><div class="pick-size-heading"><strong>เลือกไซซ์</strong><span class="muted small">เลือกจำนวนได้หลายสี หลายไซซ์</span></div><div class="pick-size-grid" role="group" aria-label="ไซซ์ของ ${esc(m.name)}">${sizes.map(s=>{const count=pickedInSize(m,s),stock=m.variants.filter(v=>pickSize(v)===s).reduce((sum,v)=>sum+Math.max(0,available(v)),0);return `<button type="button" class="pick-size ${s===size?'active':''}" data-action="pick-size" data-model="${esc(m.id)}" data-size="${esc(s)}" aria-pressed="${s===size}"><strong>${esc(s)}</strong><span data-pick-size-count="${esc(s)}">${count?`เลือก ${count}`:stock?`เหลือ ${stock}`:'หมด'}</span></button>`}).join('')}</div><div class="pick-color-heading"><strong>${m.mixed?'จำนวนแพ็ก':'เลือกสี'} · ไซซ์ ${esc(size)}</strong><span class="muted small">${colors.length} ${m.mixed?'แบบ':'สี'}</span></div>${colors.map(v=>`<div class="pick-variant"><span class="stack"><strong>${esc(pickColor(v))}</strong><span class="muted small">ขายได้ ${available(v)} แพ็ก</span></span>${available(v)>0?stepper('pick:'+m.id+':'+v.id,pickQty[m.id+':'+v.id]||0,0,available(v)):badge('หมด')}</div>`).join('')}</div>`:''}</section>`
}
function pickResults(){
  const query=pickSearch.trim().toLowerCase(),matches=data.models.filter(m=>m.initialized&&!m.hidden&&(pickCategory==='ทั้งหมด'||categoryOf(m)===pickCategory)&&(pickSubcategory==='ทั้งหมด'||subcategoryOf(m)===pickSubcategory)&&(!query||(m.name+m.id+categoryOf(m)+subcategoryOf(m)+m.variants.map(v=>v.label).join('')).toLowerCase().includes(query)));
  return `${matches.length>12?`<p class="muted small">พบ ${matches.length} รุ่น · แสดง 12 รุ่นแรก พิมพ์เพิ่มเพื่อค้นให้ตรงรุ่น</p>`:''}${matches.slice(0,12).map(pickModelCard).join('')||note('ไม่พบรุ่นที่ค้นหา ลองชื่อรุ่น รหัส ไซซ์ หรือหมวดย่อย')}`
}
function pickCart(){const rows=Object.entries(pickQty).filter(([,qty])=>Number(qty)>0);return `<div class="row"><h2 class="section-title">ตะกร้าสินค้า</h2><button class="text-action" data-action="toggle-pick-cart">กลับไปค้นหา</button></div>${rows.length?rows.map(([key,qty])=>{const [m,v]=key.split(':'),item=model(m),option=variant(m,v);return card(`<div class="stack"><strong>${esc(item.name)}</strong><span class="muted small">${esc(option.label)} · ${money(item.price)} / แพ็ก</span></div><div class="row"><span data-cart-amount="${esc(key)}">${money(item.price*qty)}</span>${stepper('pick:'+key,qty,0,available(option))}</div>`,'cart-line')}).join(''):note('ยังไม่มีสินค้าในตะกร้า')}`}
function renderPick(){const metrics=pickMetrics();return shell('เพิ่มสินค้า',pickFor==='bill'?'ขายหน้าร้าน · รุ่น → ไซซ์ → สี':'จองสินค้า · รุ่น → ไซซ์ → สี',`${pickShowCart?pickCart():`${field('ค้นหาสินค้า','pick-search',pickSearch,'ชื่อ รุ่น รหัส ไซซ์ หรือหมวดย่อย')}<div class="chiprow category-filters">${selection([['ทั้งหมด','ทั้งหมด'],...categories().map(x=>[x,x])],pickCategory,'pick-category')}</div><div class="chiprow subcategory-filters">${selection([['ทั้งหมด','ทุกหมวดย่อย'],...subcategories(pickCategory).map(x=>[x,x])],pickSubcategory,'pick-subcategory')}</div><div id="pick-results">${pickResults()}</div>`}`,`<button class="pos-cart-summary" data-action="toggle-pick-cart"><span data-pick-count>${metrics.lines} ตัวเลือก · ${metrics.packs} แพ็ก</span><strong data-pick-total>${money(metrics.total)}</strong><span aria-hidden="true">${pickShowCart?'⌃':'ดูตะกร้า ›'}</span></button>${btn(pickFor==='bill'?'เพิ่มลงบิล':'เพิ่มในการจอง','add-picked','full',metrics.packs?'':'disabled')}`)}
function renderBillDone(){const b=data.bills.find(x=>x.id===lastBillId);return shell(`บิล ${b.id}`,'ออกบิลแล้ว',`${note('ออกบิลแล้ว · สต็อกถูกตัดเรียบร้อย','good')}${b.sourceReservationId?`<button class="source-link" data-action="open-source-reservation" data-id="${b.sourceReservationId}">ขายจากการจอง ${esc(b.sourceReservationId)} · ดูรายการจองเดิม ›</button>`:''}${billPaper(b,true)}`,`${btn('พิมพ์ / บันทึกเป็น PDF','print','secondary full')}${role==='owner'?btn('แก้ไขบิล','edit-bill','secondary full',`data-id="${b.id}"`):''}${btn('ออกบิลใหม่','new-bill','full')}`)}
function billRow(b){return `<button class="reservation-row" data-action="open-bill" data-id="${b.id}"><span class="stack"><strong>${esc(b.id)} · ${esc(b.customer)}</strong><span class="muted small">${esc(b.when)} · ${b.lines.reduce((n,l)=>n+l.qty,0)} แพ็ก</span></span><strong>${money(b.total)}</strong></button>`}
function billResults(){const bills=data.bills.filter(b=>(b.customer+b.id).toLowerCase().includes(billSearch.toLowerCase())),today=new Date().toDateString(),current=bills.filter(b=>b.createdAt&&new Date(b.createdAt).toDateString()===today),older=bills.filter(b=>!current.includes(b));return `${current.length?`<h2 class="section-title">วันนี้</h2>${card(current.slice().reverse().map(billRow).join(''),'reservation-group')}`:''}${older.length?`<h2 class="section-title">ก่อนหน้า</h2>${card(older.slice().reverse().map(billRow).join(''),'reservation-group')}`:''}${!bills.length?note(billSearch?'ไม่พบบิลของลูกค้าชื่อนี้':'ยังไม่มีบิลในข้อมูลทดสอบ'):''}`}
function renderBills(){return shell('ประวัติบิล',`${data.bills.length} บิล`,`${role==='owner'?btn('กลับไปออกบิล','back','secondary full'):''}${field('ค้นหาด้วยชื่อลูกค้า','bill-search',billSearch,'พิมพ์ชื่อลูกค้า')}<div id="bill-results">${billResults()}</div>`,role==='owner'?btn('+ ออกบิลใหม่','new-bill','full'):'',false,true)}
function renderReservationNew(){const error=draft.lines.some(l=>l.qty>editableAvailable(l));return shell(editingReservationId?'แก้ไขการจอง':'จองของ',editingReservationId?editingReservationId:'ลูกค้าสั่งทาง LINE',`${error?note('จำนวนที่จองเกินสต็อกที่ขายได้','error'):''}${field('ลูกค้า','customer',draft.customer,'ต้องใส่ชื่อลูกค้าทุกการจอง')}${draft.lines.length?draftCards():card('<strong>ยังไม่มีสินค้าที่จอง</strong><p class="muted small">เพิ่มสินค้าเพื่อกันจำนวนแพ็กไว้ให้ลูกค้าคนนี้</p>','empty-hint')}${btn('+ เพิ่มสินค้า','go','secondary full','data-to="pick"')}${note('ของที่จองไว้จะขายให้คนอื่นไม่ได้จนกว่าจะเปลี่ยนเป็นบิลหรือยกเลิก')}`,`<div class="row"><span>ยอดรวม</span><span class="total">${money(draftTotal())}</span></div>${btn(editingReservationId?'บันทึกการแก้ไข':'ยืนยันการจอง','save-reservation','full',!draft.customer||!draft.lines.length||error?'disabled':'')}`)}
function reservationRow(r){return `<button class="reservation-row" data-action="open-reservation" data-id="${r.id}"><span class="stack"><strong>${esc(r.customer)}</strong><span class="muted small">${r.status==='billed'?`ซื้อแล้ว · บิล ${esc(r.billId)}`:r.status==='cancelled'?'ยกเลิกแล้ว':`${r.lines.length} รายการ · ${r.lines.reduce((n,l)=>n+l.qty,0)} แพ็ก`} · ${esc(r.when)}</span></span><strong>${money(r.total)}</strong></button>`}
function reservationResults(){const q=reservationSearch.trim().toLowerCase(),rows=data.reservations.filter(r=>r.status===reservationStatus&&(!reservationFilter||r.lines.some(l=>l.m===reservationFilter.m&&l.v===reservationFilter.v))&&(!q||(r.customer+r.id+r.billId).toLowerCase().includes(q)));if(reservationStatus!=='active')return rows.length?card(rows.slice().reverse().map(reservationRow).join(''),'reservation-group'):note('ไม่มีรายการในหมวดนี้');const overdue=rows.filter(r=>r.createdAt&&Date.now()-new Date(r.createdAt).getTime()>2*86400000),recent=rows.filter(r=>!overdue.includes(r));return `${overdue.length?note(`ค้างเกิน 2 วัน ${overdue.length} รายการ · ทักลูกค้าเรื่องโอนเงินหรือยกเลิกเพื่อปล่อยของกลับมาขาย`,'warn'):''}${overdue.length?`<h2 class="section-title">ค้างเกิน 2 วัน</h2>${card(overdue.slice().reverse().map(reservationRow).join(''),'reservation-group')}`:''}${recent.length?`<h2 class="section-title">ล่าสุด</h2>${card(recent.slice().reverse().map(reservationRow).join(''),'reservation-group')}`:''}${!rows.length?note('ไม่มีการจองที่ตรงกับรายการนี้'):''}`}
function renderReservations(){const active=data.reservations.filter(r=>r.status==='active').length,billed=data.reservations.filter(r=>r.status==='billed').length,cancelled=data.reservations.filter(r=>r.status==='cancelled').length;return shell('การจอง',`${active} รายการที่รอซื้อ`,`${reservationFilter?note(`กำลังแสดงการจองของ ${esc(model(reservationFilter.m).name)} · ${esc(variant(reservationFilter.m,reservationFilter.v).label)}`)+btn('ดูการจองทั้งหมด','clear-reservation-filter','secondary full'):''}<div class="chiprow reservation-status">${selection([['active',`รอซื้อ (${active})`],['billed',`ซื้อแล้ว (${billed})`],['cancelled',`ยกเลิก (${cancelled})`]],reservationStatus,'reservation-status')}</div>${field('ค้นหาลูกค้าหรือเลขรายการ','reservation-search',reservationSearch)}<div id="reservation-results">${reservationResults()}</div>`,role==='owner'?btn('+ จองของ','new-reservation','full'):'',false,false)}
function renderReservationDetail(){const r=data.reservations.find(x=>x.id===reservationId),active=r.status==='active';return shell(`การจองของ${esc(r.customer)}`,`${r.id} · จองเมื่อ ${r.when}`,`${toast?note(toast,'good'):''}${r.status==='billed'?note(`ขายแล้ว · บิล ${esc(r.billId)}`,'good'):r.status==='cancelled'?note('ยกเลิกแล้ว · ของกลับมาขายได้','warn'):note(`ของ ${r.lines.reduce((n,l)=>n+l.qty,0)} แพ็กยังถูกจองไว้`)}${card(`${r.lines.map(l=>`<div class="row"><span>${esc(lineLabel(l))}<br><span class="muted small">${l.qty} แพ็ก คูณ ${money(l.price)}</span></span><strong>${money(lineAmount(l))}</strong></div>`).join('')}`)}<div class="row"><span>${active?'ยอดที่ตกลง':'ยอดรายการเดิม'}</span><strong class="total">${money(r.total)}</strong></div>`,r.status==='billed'?btn(`ดูบิล ${r.billId}`,'open-linked-bill','full'):active&&role==='owner'?`${btn('ดูสรุปยอดก่อนขาย','preview-reservation-bill','full')}${btn('แก้ไขการจอง','edit-reservation','secondary full')}${btn('ยกเลิกการจอง','ask-cancel-reservation','danger full')}`:'')}
