function renderCatalogue(){const visible=data.models.filter(m=>m.initialized&&!m.hidden);return `<main class="phone" data-screen="catalogue"><div class="catalog-head"><div class="home-wordmark" role="img" aria-label="khonnai"></div><h1>แคตตาล็อกสินค้า</h1><p>${esc(data.shop)} · เลือกรุ่นที่สนใจแล้วทักร้าน</p></div><div class="content catalogue-content">${visible.map(m=>card(`<div class="row start">${productThumb(m)}<div class="stack" style="flex:1"><span class="product-eyebrow">${esc(categoryOf(m))} / ${esc(subcategoryOf(m))}</span><h2>${esc(m.name)}</h2><span class="muted small">${m.pack} ตัว/แพ็ก · ${m.mixed?'คละสี':'เลือกสีได้'}</span><strong class="catalog-price">${money(m.price)} / แพ็ก</strong></div></div><div class="chiprow">${m.variants.map(v=>`<span class="badge ${status(m,v)==='หมด'?'bad':status(m,v)==='ใกล้หมด'?'warn':'good'}">${esc(v.label)} · ${status(m,v)}</span>`).join('')}</div>`,'catalog-card')).join('')}${btn('กลับหน้าเจ้าของร้าน','go','secondary full','data-to="home"')}</div>${data.line?footer(btn('ทักแชต LINE ของร้าน','open-line','full')):footer('สนใจรุ่นไหน ทักร้านเพื่อสั่งซื้อ')}</main>`}
