// Photos stay in the prototype's in-memory data. Resize before storing so a phone photo
// does not create a huge DOM data URL in every product card and catalogue view.
async function readProductPhoto(file){
  if(!file||!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(file.type))throw Error('อัปโหลดไม่ได้: เลือกไฟล์ JPG, PNG, WebP หรือ HEIC');
  if(file.size>15*1024*1024)throw Error('อัปโหลดไม่ได้: รูปต้องไม่เกิน 15 MB');
  const url=URL.createObjectURL(file);
  try{
    const image=await new Promise((resolve,reject)=>{const candidate=new Image();candidate.onload=()=>resolve(candidate);candidate.onerror=()=>reject(Error('อัปโหลดไม่ได้: เปิดรูปนี้ไม่สำเร็จ ลองใช้ JPG หรือ PNG'));candidate.src=url});
    const scale=Math.min(1,960/Math.max(image.naturalWidth,image.naturalHeight));
    const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
    const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
    return canvas.toDataURL('image/jpeg',.84);
  }finally{URL.revokeObjectURL(url)}
}
document.addEventListener('change',async e=>{const key=e.target.dataset.field;if(!key)return;
  if(key==='new-photo'||key==='model-photo'){
    const file=e.target.files?.[0];if(!file)return;
    const draft=newModel,id=selectedModel;
    try{const photo=await readProductPhoto(file);if(key==='new-photo'&&newModel===draft)draft.photo=photo;else if(key==='model-photo'&&role==='owner')model(id).photo=photo;else return;toast='บันทึกรูปในข้อมูลทดสอบแล้ว';render()}
    catch(error){toast=error.message;render()}
    return;
  }
  if(key==='receipt-model'){receipt.model=e.target.value;receipt.variant=model(receipt.model).variants[0].id;render()}else if(key==='receipt-variant')receipt.variant=e.target.value;
});
function finishModel(skip){const n=newModel,id=n.name.match(/[A-Z]+-\d+/)?.[0]||'M-'+String(data.models.length+1).padStart(3,'0');if(data.models.some(m=>m.id===id))return noticeToast('รหัสรุ่นนี้มีอยู่แล้ว');if(!validPrice(n.price)||!validPackCount(n.pack)||!validAlertThreshold(n.min))return noticeToast('ราคา จำนวนตัวต่อแพ็ก หรือจุดเตือนไม่ถูกต้อง');if(!n.sizes.length||n.sizes.some(size=>!validSize(size,n.sizeSystem)))return noticeToast('ไซซ์ไม่ตรงกับชุดที่เลือก');if(!n.mixed&&n.sizes.some(size=>!(n.colors[size]||[]).length))return noticeToast('กรุณาเลือกสีสำหรับทุกไซซ์');if(!skip&&!stockSummary(n).complete)return noticeToast('กรอกยอดจริงทุกแบบเป็นจำนวนเต็ม 0–999 หรือข้ามสต็อกตั้งต้น');const variants=n.sizes.flatMap(size=>(n.mixed?['คละสี']:(n.colors[size]||[])).map(color=>({id:size+'-'+color,label:size+' · '+color,onHand:skip?0:n.stocks[size+':'+color],reserved:0})));data.models.push({id,name:n.name,category:n.category.trim(),subcategory:n.subcategory.trim(),photo:n.photo||null,sizeSystem:n.sizeSystem,pack:n.pack,mixed:n.mixed,price:n.price,min:n.min,hidden:false,initialized:!skip,variants});newModel=blankModel();selectedModel=id;page='stock';noticeToast(skip?'บันทึกรุ่นแล้ว ยังไม่แสดงในแคตตาล็อกจนกว่าจะกรอกสต็อกตั้งต้น':'บันทึกรุ่นและสต็อกตั้งต้นแล้ว')}
if(location.hash==='#catalogue')page='catalogue';render();




